declare(strict_types=1);require dirname(__DIR__).'/bootstrap.php';use App\Core\Database;use App\Services\LiveDisplaySessionService;$pdo=Database::connection();$token=trim((string)($_GET['token']??''));$s=LiveDisplaySessionService::byToken($pdo,$token);if(!$s||!$s['auto_page']||!in_array($s['screen_type'],['competitors','callbacks','finalists'],true)){http_response_code(204);exit;}$stateUrl=url('live-display/state.php?token='.rawurlencode($token));$test=$s['data_mode']==='test';$entryTable=$test?'bdc_test_scoring_entries':'bdc_scoring_entries';$count=0;$roleCounts=['leader'=>0,'follower'=>0];if(in_array($s['screen_type'],['competitors','callbacks','finalists'],true)){$q=$pdo->prepare($s['screen_type']==='competitors'?"SELECT dance_role,COUNT(*) total FROM {$entryTable} WHERE round_id=:r AND entry_status='active' GROUP BY dance_role":"SELECT se.dance_role,COUNT(*) total FROM {$resultTable} sr JOIN {$entryTable} se ON se.id=sr.entry_id WHERE sr.round_id=:r AND sr.result_status IN('callback','alternate') GROUP BY se.dance_role");$q->execute(['r'=>$s['current_round_id']]);foreach($q->fetchAll() as $row){$role=(string)($row['dance_role']??'');if(isset($roleCounts[$role]))$roleCounts[$role]=(int)$row['total'];}$count=array_sum($roleCounts);}else{$q=$pdo->prepare("SELECT COUNT(*) FROM {$entryTable} WHERE round_id=:r AND entry_status='active'");$q->execute(['r'=>$s['current_round_id']]);$count=(int)$q->fetchColumn();}$settings=\App\Services\ProjectionSettingsService::get($pdo,(int)$s['current_round_id'],$test);$layout=\App\Services\ProjectionLayoutService::resolve((string)$settings['screen_format'],max(1,$count),(string)$settings['density'],$settings['custom_width']?:null,$settings['custom_height']?:null);$pages=in_array($s['screen_type'],['competitors','callbacks','finalists'],true)?max(1,(int)ceil(max($roleCounts)/max(1,(int)$layout['rows']*max(1,(int)floor((int)$layout['columns']/2))))):max(1,(int)$layout['pages']);$next=((int)$s['page_number']%$pages)+1;$pdo->prepare("UPDATE bdc_live_display_sessions SET page_number=:p,state_version=state_version+1,updated_at=NOW() WHERE id=:id")->execute(['p'=>$next,'id'=>$s['id']]);http_response_code(204);